function chart(id,title,sub,labels,values,unit='money',controls=''){
  const max=Math.max(...values,1),rough=max*1.12,power=Math.pow(10,Math.floor(Math.log10(rough))),ceiling=Math.ceil(rough/power)*power;
  const selected=ui.charts[id]?.selected??values.length-1,fmt=v=>unit==='money'?money(v):v.toLocaleString('en-KE')+(unit==='percent'?'%':'');
  ui.charts[id]={labels,values,unit,selected};
  return `<section class="card chart-card">${cardHeader(title,sub,controls)}${unit==='money'?`<div class="chart-summary"><strong class="money">${whole(values.at(-1)||0)}</strong><span>latest period</span>${trendBadge(values.at(-1)||0,values.at(-2)||0)}</div>`:''}<div class="chart" role="group" aria-label="${esc(title)} — select a bar for details"><div class="chart-axis" aria-hidden="true">${[0,1,2,3,4].map(i=>`<span>${unit==='money'?compact(ceiling*i/4):Math.round(ceiling*i/4)+(unit==='percent'?'%':'')}</span>`).join('')}</div>${values.map((v,i)=>{const change=i===0?'flat':v>values[i-1]?'up':v<values[i-1]?'down':'flat';return `<div class="chart-column"><button class="chart-bar ${change} ${selected===i?'selected':''}" style="height:${Math.max(2,v/ceiling*88)}%" data-action="chart-bar" data-chart="${id}" data-index="${i}" aria-label="${esc(labels[i])}: ${fmt(v)}, ${change==='up'?'increase':change==='down'?'decrease':'baseline or no change'}" aria-pressed="${selected===i}"></button><span>${esc(labels[i])}</span></div>`;}).join('')}</div><div class="chart-detail" id="chart-detail-${id}" aria-live="polite">${esc(labels[selected]||'')} · ${fmt(values[selected]||0)}${selected>0?` · ${values[selected]===values[selected-1]?'No change':(values[selected]>values[selected-1]?'Increase':'Decrease')} vs previous period`: ' · Baseline period'}</div><div class="chart-legend"><span><i class="legend-dot up"></i>Increase</span><span><i class="legend-dot down"></i>Decrease</span><span><i class="legend-dot"></i>Normal / no change</span></div></section>`;
}
function collectionChart(id='collection',mode=ui.chartMode){
  const h=state.historical[mode==='t'?'terms':'months'];const labels=[...h.labels,mode==='t'?`T${state.settings.term.slice(-1)} ’${String(state.settings.year).slice(-2)}`:new Date().toLocaleDateString('en-KE',{month:'short'})];
  const values=[...h.values,mode==='t'?totals().collected:sum(currentPayments().filter(p=>p.date.startsWith(today().slice(0,7))))];
  return chart(id,'Fee collection','Collections against the previous period',labels,values,'money',id==='collection'?`<div class="segmented" aria-label="Collection period"><button data-action="chart-mode" data-mode="m" class="${mode==='m'?'active':''}" aria-pressed="${mode==='m'}">Monthly</button><button data-action="chart-mode" data-mode="t" class="${mode==='t'?'active':''}" aria-pressed="${mode==='t'}">By term</button></div>`:'');
}
function sparkline(){
  const dates=[...new Set([...state.payments,...state.expenses].map(t=>t.date))].sort().slice(-10);let running=sum(state.accounts,a=>a.opening);const all=[...state.payments,...state.expenses].sort((a,b)=>a.date.localeCompare(b.date));let cursor=0;
  const vals=dates.map(d=>{while(cursor<all.length&&all[cursor].date<=d){const t=all[cursor++];running+=('invoiceId' in t?t.amount:-t.amount);}return running;});if(vals.length<2)vals.unshift(running);
  const min=Math.min(...vals)*.97,max=Math.max(...vals)*1.02,range=max-min||1;const pts=vals.map((v,i)=>[i/(vals.length-1)*400,95-(v-min)/range*75]);const line=pts.map((p,i)=>(i?'L':'M')+p.join(' ')).join(' ');
  return `<svg class="sparkline" viewBox="0 0 400 110" preserveAspectRatio="none" role="img" aria-label="Account balance trend across recent transaction dates"><defs><linearGradient id="balance-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#386bd7" stop-opacity=".2"/><stop offset="1" stop-color="#386bd7" stop-opacity="0"/></linearGradient></defs><path d="${line} L400 110 H0Z" fill="url(#balance-fill)"/><path d="${line}" fill="none" stroke="#386bd7" stroke-width="2.5" vector-effect="non-scaling-stroke"/></svg>`;
}
function paymentTable(rows){return `<div class="table-wrap"><table class="payment-table"><thead><tr><th>Student</th><th>Date</th><th>Payment method</th><th>Status</th><th>Amount</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${who(student(p.studentId))}</td><td class="muted">${shortDate(p.date)}</td><td>${esc(p.method)}</td><td>${badge('Received','green')}</td><td class="money">${money(p.amount)} <button class="text-button" data-action="receipt" data-id="${esc(p.id)}" aria-label="Print receipt ${esc(p.id)}">${icon('receipt')}</button></td></tr>`).join('')}</tbody></table></div>`;}
