  const rows=state.assessments.filter(a=>{const f=ui.filters.cbc||{},s=student(a.studentId);return (!f.q||[s.name,a.area,a.strand,a.comment].join(' ').toLowerCase().includes(f.q.toLowerCase().trim()))&&(!f.area||a.area===f.area)&&(!f.level||a.level===f.level);}).sort((a,b)=>b.date.localeCompare(a.date));const p=paginate('cbc',rows);
